    "titleAr": "جهد الإيقاف وأقصى طاقة حركة للإلكترونات الضوئية #10",
    "difficulty": "medium",
    "questionEn": "Monochromatic light of photon energy $E_{\\text{photon}} = 5\\text{ eV}$ falls on a metal having a work function $W_0 = 3\\text{ eV}$. What is the stopping potential $V_{\\text{stop}}$ required to completely halt the emitted photoelectrons?",
    "questionAr": "سقط ضوء أحادي اللون طاقة فوتوناته $E_{\\text{photon}} = 5\\text{ eV}$ على فلز دالة الشغل له $W_0 = 3\\text{ eV}$. ما جهد الإيقاف $V_{\\text{stop}}$ اللازم لمنع وصول أسرع الإلكترونات الضوئية المنبعثة؟",
    "optionsEn": [
      "$V_{\\text{stop}} = 2\\text{ V}$",
      "$V_{\\text{stop}} = 4.00\\text{ V}$",
      "$V_{\\text{stop}} = 5\\text{ V}$",
      "$V_{\\text{stop}} = 3\\text{ V}$"
    ],
    "optionsAr": [
      "$V_{\\text{stop}} = 2\\text{ V}$",
      "$V_{\\text{stop}} = 4.00\\text{ V}$",
      "$V_{\\text{stop}} = 5\\text{ V}$",
      "$V_{\\text{stop}} = 3\\text{ V}$"
    ],
    "correctAnswer": "$V_{\\text{stop}} = 2\\text{ V}$",
    "correctIndex": 0,
    "hintEn": "Apply Einstein's equation: $KE_{\\max} = E_{\\text{photon}} - W_0 = e V_{\\text{stop}}$. The stopping potential in Volts is numerically equal to $KE_{\\max}$ in electron-volts.",
    "hintAr": "طبق معادلة أينشتاين: $KE_{\\max} = E_{\\text{photon}} - W_0 = e V_{\\text{stop}}$. قيمة جهد الإيقاف بالفولت تساوي عددياً أقصى طاقة حركة بالإلكترون-فولت.",
    "stepByStepSolutionEn": [
      "Einstein's photoelectric relation: $KE_{\\max} = E_{\\text{photon}} - W_0$.",
      "$$KE_{\\max} = 5 - 3 = 2\\text{ eV}$$",
      "Since $KE_{\\max} = e \\cdot V_{\\text{stop}}$, the stopping potential is:",
      "$$V_{\\text{stop}} = 2\\text{ V}$$"
    ],
    "stepByStepSolutionAr": [
      "معادلة أينشتاين للظاهرة الكهروضوئية: $KE_{\\max} = E_{\\text{photon}} - W_0$.",
      "$$KE_{\\max} = 5 - 3 = 2\\text{ إلكترون-فولت}$$",
      "بما أن $KE_{\\max} = e \\cdot V_{\\text{stop}}$، فإن جهد الإيقاف يساوي:",
      "$$V_{\\text{stop}} = 2\\text{ فولت}$$"
    ],
    "teacherTipEn": "Increasing the light intensity increases the photocurrent (number of electrons) but DOES NOT change the stopping potential or kinetic energy.",
    "teacherTipAr": "زيادة شدة الضوء الساقط تزيد من شدة التيار الكهروضوئي (عدد الإلكترونات) ولكنها لا تغير مطلقاً من جهد الإيقاف أو طاقة الحركة العظمى."
