    "questionAr": "اصطدم فوتون من أشعة إكس بإلكترون حر ساكن وتشتت بزاوية $\\theta = 60^\\circ$. احسب مقدار الزيادة في الطول الموجي للفوتون $\\Delta \\lambda = \\lambda' - \\lambda$ بوحدة البيكومتر ($\\text{pm}$ حيث طول موجة كومتون $\\lambda_C = \\frac{h}{m_e c} = 2.43\\text{ pm}$).",
