    "questionAr": "عند إضاءة سطح فلز بضوء تردده $\\nu_1 = 6.2 \\times 10^{14}\\text{ Hz}$ كان جهد الإيقاف $V_1 = 0.57\\text{ V}$. وعند إضاءته بضوء تردده $\\nu_2 = 9.3 \\times 10^{14}\\text{ Hz}$ أصبح جهد الإيقاف $V_2 = 1.85\\text{ V}$. احسب ثابت بلانك $h$ من هذه النتائج العملية.",
