    "questionAr": "عند إضاءة سطح فلز بضوء تردده $\\nu_1 = 8.0 \\times 10^{14}\\text{ Hz}$ كان جهد الإيقاف $V_1 = 1.31\\text{ V}$. وعند إضاءته بضوء تردده $\\nu_2 = 12.0 \\times 10^{14}\\text{ Hz}$ أصبح جهد الإيقاف $V_2 = 2.97\\text{ V}$. احسب ثابت بلانك $h$ من هذه النتائج العملية.",
