    "questionAr": "عند إضاءة سطح فلز بضوء تردده $\\nu_1 = 9.2 \\times 10^{14}\\text{ Hz}$ كان جهد الإيقاف $V_1 = 1.81\\text{ V}$. وعند إضاءته بضوء تردده $\\nu_2 = 13.8 \\times 10^{14}\\text{ Hz}$ أصبح جهد الإيقاف $V_2 = 3.71\\text{ V}$. احسب ثابت بلانك $h$ من هذه النتائج العملية.",
