      "$$h = \\frac{e(V_2 - V_1)}{\\nu_2 - \\nu_1} = \\frac{1.6 \\times 10^{-19} \\times (3.71 - 1.81)}{(13.8 - 9.2) \\times 10^{14}} = 6.63 \\times 10^{-34}\\text{ J}\\cdot\\text{s}$$"
